import{_ as a,o,c as n,a2 as t}from"./chunks/framework.Do1fvF3d.js";const p=JSON.parse('{"title":"Is your number shown wrongly?","description":"","frontmatter":{},"headers":[],"relativePath":"en/guia/apelacion.md","filePath":"en/guia/apelacion.md","lastUpdated":null}'),r={name:"en/guia/apelacion.md"};function i(s,e,l,u,h,m){return o(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="is-your-number-shown-wrongly" tabindex="-1">Is your number shown wrongly? <a class="header-anchor" href="#is-your-number-shown-wrongly" aria-label="Permalink to &quot;Is your number shown wrongly?&quot;">​</a></h1><p>You do not need an account or the app.</p><h2 id="hide-the-names-linked-to-your-number" tabindex="-1">Hide the names linked to your number <a class="header-anchor" href="#hide-the-names-linked-to-your-number" aria-label="Permalink to &quot;Hide the names linked to your number&quot;">​</a></h2><p>If your number shows a name you do not want displayed, we can hide it. Hiding names does <strong>not</strong> change whether a number is marked as spam, so nobody can use it to clean a spam number.</p><h2 id="my-number-is-not-spam" tabindex="-1">&quot;My number is not spam&quot; <a class="header-anchor" href="#my-number-is-not-spam" aria-label="Permalink to &quot;&quot;My number is not spam&quot;&quot;">​</a></h2><p>If your number is marked as spam by mistake, write to us. We review every request by hand and answer within the deadlines of Colombian law (inquiries within 10 business days, complaints within 15 business days).</p><h2 id="how-to-ask" tabindex="-1">How to ask <a class="header-anchor" href="#how-to-ask" aria-label="Permalink to &quot;How to ask&quot;">​</a></h2><p>For now, write to <span class="placeholder">[CONTACT EMAIL]</span> with:</p><ul><li>the number (with country code, for example +57 300 123 4567),</li><li>what you want: hide the names or review the spam marking,</li><li>optionally, why you think it is a mistake.</li></ul><p>We use the number only to handle your request and do not keep it after resolving it. A form will be available on this page soon.</p>',10)])])}const c=a(r,[["render",i]]);export{p as __pageData,c as default};
